/** Names the site can actually draw. The admin icon picker should read this
 * list, so the operator picks from what renders instead of guessing lucide
 * names and discovering the "?" fallback afterwards. */
export const supportedIconNames = Object.keys(iconMap).sort();

export function hasIcon(name: string): boolean {
  return Object.prototype.hasOwnProperty.call(iconMap, String(name || '').toLowerCase());
}
